operations.search:
const needle =
  "defineFrameConnFeature";


let searchIndex =
  0;


while (
  true
) {
  const callIndex =
    text.indexOf(
      needle,
      searchIndex
    );


  if (
    callIndex <
    0
  ) {
    break;
  }


  const openParenthesis =
    text.indexOf(
      "(",
      callIndex +
      needle.length
    );


  if (
    openParenthesis <
    0
  ) {
    break;
  }

operations.replace:
const callPattern =
  /\bdefineFrameConnFeature\s*\(/g;


let searchIndex =
  0;


while (
  true
) {
  callPattern.lastIndex =
    searchIndex;


  const callMatch =
    callPattern.exec(
      text
    );


  if (
    !callMatch
  ) {
    break;
  }


  const callIndex =
    callMatch.index;


  const openParenthesis =
    text.indexOf(
      "(",
      callIndex
    );


  if (
    openParenthesis <
    0
  ) {
    break;
  }

